60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
112	        prepareNewOwner(ownerFieldsDto, registrationDate);
113	        HttpHeaders headers = new HttpHeaders();
114	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
115	        owner.setRegistrationDate(registrationDate);
116	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
117	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
118	        assignHousehold(owner, ownerFieldsDto);
119	        this.clinicService.saveOwner(owner);
120	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
121	        headers.setLocation(UriComponentsBuilder.newInstance()
122	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
123	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
129	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
130	        if (currentOwner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        currentOwner.setAddress(ownerFieldsDto.getAddress());
134	        currentOwner.setCity(ownerFieldsDto.getCity());
135	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
136	        currentOwner.setLastName(ownerFieldsDto.getLastName());
137	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
138	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
139	        this.clinicService.saveOwner(currentOwner);
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Transactional
145	    @Override
146	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        this.clinicService.deleteOwner(owner);
152	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        HttpHeaders headers = new HttpHeaders();
163	        Pet pet = petMapper.toPet(petFieldsDto);
164	        owner.setId(ownerId);
165	        pet.setOwner(owner);
166	        pet.getType().setName(null);
167	        this.clinicService.savePet(pet);
168	        PetDto petDto = petMapper.toPetDto(pet);
169	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
170	            .buildAndExpand(pet.getId()).toUri());
171	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
177	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
178	        if (currentOwner != null) {
179	            Pet currentPet = this.clinicService.findPetById(petId);
180	            if (currentPet != null) {
181	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
182	                currentPet.setName(petFieldsDto.getName());
183	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
184	                this.clinicService.savePet(currentPet);
185	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
186	            }
187	        }
188	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
194	        HttpHeaders headers = new HttpHeaders();
195	        Visit visit = visitMapper.toVisit(visitFieldsDto);
196	        Pet pet = new Pet();
197	        pet.setId(petId);
198	        visit.setPet(pet);
199	        this.clinicService.saveVisit(visit);
200	        VisitDto visitDto = visitMapper.toVisitDto(visit);
201	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
202	            .buildAndExpand(visit.getId()).toUri());
203	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
204	    }
205	
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
210	        Owner owner = this.clinicService.findOwnerById(ownerId);
211	        if (owner != null) {
212	            Pet pet = owner.getPet(petId);
213	            if (pet != null) {
214	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
215	            }
216	        }
217	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	    }
219	
220	    /**
221	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
222	     * The address is normalized in place (so a required-field check that follows rejects an
223	     * address blank after normalization), the required fields are checked, the telephone and
224	     * email are normalized in place, and the resulting telephone is rejected when it already
225	     * belongs to another owner. Each rule
226	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
227	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
228	     * to be mapped and saved.
229	     *
230	     * @param ownerFieldsDto the submitted owner fields, normalized in place
231	     */
232	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
233	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
234	        validateRequiredFields(ownerFieldsDto);
235	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
236	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
237	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
238	        rejectDuplicateHousehold(ownerFieldsDto);
239	        rejectCityAtCapacity(ownerFieldsDto.getCity());
240	        rejectDailyLimitExceeded(registrationDate);
241	    }
242	
243	    /**
244	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
245	     * falls on a business day. The date supplied on the request is used when present, otherwise the
246	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
247	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
248	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
249	     * membership number's year segment, the per-day create limit) is computed against.
250	     *
251	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
252	     * @return the effective registration date rolled forward to the next business day
253	     */
254	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
255	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
256	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
257	        return toBusinessDay(effective);
258	    }
259	
260	    /**
261	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
262	     * following Monday, while a weekday is returned unchanged.
263	     *
264	     * @param date the date to adjust
265	     * @return the same date when it is a weekday, otherwise the next Monday
266	     */
267	    private LocalDate toBusinessDay(LocalDate date) {
268	        java.time.DayOfWeek day = date.getDayOfWeek();
269	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
270	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
271	        }
272	        return date;
273	    }
274	
275	    /**
276	     * The maximum number of owners that may be created on a single day. Once this many owners
277	     * already carry today's {@code registrationDate}, no further owner may be created today.
278	     */
279	    private static final long DAILY_OWNER_LIMIT = 100L;
280	
281	    /**
282	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
283	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
284	     * date the new owner would be stored with, so owners are capped per business day. When the limit
285	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
286	     * advice renders as a 429 Too Many Requests response.
287	     *
288	     * @param registrationDate the adjusted business-day registration date of the owner being created
289	     */
290	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
291	        long count = this.clinicService.findAllOwners().stream()
292	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
293	            .count();
294	        if (count >= DAILY_OWNER_LIMIT) {
295	            throw new DailyOwnerLimitExceededException(registrationDate);
296	        }
297	    }
298	
299	    /**
300	     * The maximum number of owners a single city may hold. Once a city already contains this
301	     * many owners, no further owner may be created in it.
302	     */
303	    private static final long CITY_OWNER_CAPACITY = 50L;
304	
305	    /**
306	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
307	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
308	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
309	     * which the exception advice renders as a 409 Conflict response.
310	     *
311	     * @param city the city of the owner being created
312	     */
313	    private void rejectCityAtCapacity(String city) {
314	        long count = this.clinicService.findAllOwners().stream()
315	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
316	            .count();
317	        if (count >= CITY_OWNER_CAPACITY) {
318	            throw new CityCapacityExceededException(city);
319	        }
320	    }
321	
322	    /**
323	     * Builds the customer code assigned to a newly created owner. The code is formatted as
324	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
325	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
326	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
327	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
328	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
329	     *
330	     * @param city the owner's city
331	     * @param lastName the owner's last name
332	     * @return the formatted customer code
333	     */
334	    private String nextCustomerCode(String city, String lastName) {
335	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
336	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
337	        long sequence = this.clinicService.findAllOwners().stream()
338	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
339	            .count() + 1L;
340	        return String.format("%s-%s-%04d", city3, last3, sequence);
341	    }
342	
343	    /**
344	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
345	     * with the owner being created, compared case-insensitively. The count is taken before the
346	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
347	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
348	     *
349	     * @param firstName the first name of the owner being created
350	     * @param lastName the last name of the owner being created
351	     * @return the number of pre-existing owners sharing the same first and last name
352	     */
353	    private int countNamesakes(String firstName, String lastName) {
354	        return (int) this.clinicService.findAllOwners().stream()
355	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
356	                && lastName.equalsIgnoreCase(existing.getLastName()))
357	            .count();
358	    }
359	
360	    /**
361	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
362	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
363	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
364	     * the names of every offending field, which the exception advice renders as a 400 response
365	     * with an {@code errors} array.
366	     *
367	     * @param ownerFieldsDto the submitted owner fields
368	     */
369	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
370	        List<String> missing = new ArrayList<>();
371	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
372	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
373	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
374	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
375	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
376	        if (!missing.isEmpty()) {
377	            throw new RequiredFieldsMissingException(missing);
378	        }
379	    }
380	
381	    private void addIfBlank(List<String> missing, String fieldName, String value) {
382	        if (value == null || value.isBlank()) {
383	            missing.add(fieldName);
384	        }
385	    }
386	
387	    /**
388	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
389	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
390	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
391	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
392	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
393	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
394	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
395	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
396	     *
397	     * @param telephone the submitted telephone value
398	     * @return the normalized E.164 telephone
399	     */
400	    private String normalizeTelephone(String telephone) {
401	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
402	        String e164;
403	        if (cleaned.startsWith("+")) {
404	            e164 = "+" + cleaned.substring(1);
405	        } else {
406	            String national = cleaned;
407	            if (national.startsWith("0")) {
408	                national = national.substring(1);
409	            }
410	            e164 = "+61" + national;
411	        }
412	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
413	            throw new InvalidFieldsException(List.of("telephone"));
414	        }
415	        return e164;
416	    }
417	
418	    /**
419	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
420	     * and a domain containing at least one dot, none of the parts holding whitespace or a
421	     * second {@code @}.
422	     */
423	    private static final java.util.regex.Pattern EMAIL_PATTERN =
424	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
425	
426	    /**
427	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
428	     * accepted and returned unchanged. When present it must be a syntactically valid address;
429	     * the value is stored and returned lower-cased. When present but invalid an
430	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
431	     * response naming the {@code email} field.
432	     *
433	     * @param email the submitted email value, or {@code null} when omitted
434	     * @return the lower-cased email, or {@code null} when none was supplied
435	     */
436	    private String normalizeEmail(String email) {
437	        if (email == null) {
438	            return null;
439	        }
440	        String trimmed = email.trim();
441	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
442	            throw new InvalidFieldsException(List.of("email"));
443	        }
444	        return trimmed.toLowerCase(java.util.Locale.ROOT);
445	    }
446	
447	    /**
448	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
449	     * The telephone is stored in its normalized E.164 form, so a plain equality check
450	     * against every owner's telephone compares E.164 values. When a match is found a
451	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
452	     * 409 Conflict response.
453	     *
454	     * @param telephone the normalized telephone of the owner being created
455	     */
456	    private void rejectDuplicateTelephone(String telephone) {
457	        boolean taken = this.clinicService.findAllOwners().stream()
458	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
459	        if (taken) {
460	            throw new DuplicateTelephoneException(telephone);
461	        }
462	    }
463	
464	    /**
465	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
466	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
467	     * for how that identity is compared). A request may bypass this rule by setting
468	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
469	     * When a household mate is found and the request did not opt in a
470	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
471	     * Conflict response.
472	     *
473	     * @param ownerFieldsDto the submitted owner fields
474	     */
475	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
476	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
477	            return;
478	        }
479	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
480	        if (taken) {
481	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
482	        }
483	    }
484	
485	    /**
486	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
487	     * set to {@code true}. The identifier is derived deterministically from the owner's
488	     * household identity (its {@code lastName} and {@code address}, see
489	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
490	     * the same stable value. The new owner receives that value, and any existing household mates
491	     * that do not yet carry it are updated so the whole household shares one identifier. When the
492	     * request did not opt in the owner is left without a household identifier.
493	     *
494	     * @param owner the newly created owner, mutated in place with its household identifier
495	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
496	     */
497	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
498	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
499	            return;
500	        }
501	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
502	        owner.setHouseholdId(householdId);
503	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
504	            if (!householdId.equals(mate.getHouseholdId())) {
505	                mate.setHouseholdId(householdId);
506	                this.clinicService.saveOwner(mate);
507	            }
508	        }
509	    }
510	
511	    /**
512	     * Derives the stable {@code householdId} shared by every owner in the household identified by
513	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
514	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
515	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
516	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
517	     *
518	     * @param lastName the household's last name
519	     * @param address the household's address
520	     * @return the deterministic household identifier
521	     */
522	    private String householdIdFor(String lastName, String address) {
